    /// Parsed once: 1 where inside the silhouette, else 0 (row-major, GW*GH).
    public static readonly byte[] Mask = BuildMask();

    private static byte[] BuildMask()
    {
        if (MaskString.Length != GW * GH)
            throw new InvalidOperationException("KIWI mask length mismatch: " + MaskString.Length);
        var a = new byte[GW * GH];
        for (int i = 0; i < MaskString.Length; i++) a[i] = (byte)(MaskString[i] == '1' ? 1 : 0);
        return a;
    }

    /// Mirrors maskOn(x, y): bounds-checked, y is row from the TOP.
    public static bool MaskOn(int x, int y)
    {
        if (x < 0 || y < 0 || x >= GW || y >= GH) return false;
        return Mask[y * GW + x] == 1;
    }
